app.get("/api/supabase/health", async (_req, res) => {
  const tables = [
    "users",
    "user_usage",
    "analysis_history",
    "feedback",
    "promo_codes",
    "transactions",
    "system_settings"
  ];
  if (!supabaseAdmin) {
    return res.status(503).json({
      configured: false,
      error: "Supabase service role client is not configured on the server."
    });
  }
  const baseUrl = supabaseUrl.replace(/\/$/, "");
  const key = supabaseServiceRoleKey || supabaseAnonKey;
  const results = {};
  for (const table of tables) {
    try {
      const response = await fetch(`${baseUrl}/rest/v1/${table}?select=*&limit=1`, {
        headers: { apikey: key, Authorization: `Bearer ${key}` }
      });
      if (response.ok) {
        results[table] = "ok";
        continue;
      }
      const body = await response.text();
      let parsed = null;
      try {
        parsed = JSON.parse(body);
      } catch {
      }
      results[table] = `HTTP ${response.status} ${parsed?.code || ""} ${parsed?.message || body.slice(0, 120)}`.trim();
    } catch (err) {
      results[table] = `network error: ${err?.name || "Error"} ${err?.message || ""}`.trim();
    }
  }
  const healthy = Object.values(results).every((value) => value === "ok");
  const permissionDenied = Object.values(results).some((value) => value.includes("42501"));
  return res.status(healthy ? 200 : 500).json({
    configured: true,
    healthy,
    tables: results,
    hint: healthy ? "All required tables are readable with the service role key." : permissionDenied ? "Tables exist but the service_role role lacks privileges. Run supabase/grants.sql in the Supabase SQL editor." : "Run supabase/schema.sql in the Supabase SQL editor to create the missing tables."
  });
});
